    ('b364-module',
     '        function nxStatsGroupOn() {',
     '        // ============ b364: ОБЩИЙ ПРОГРЕСС МЕЖДУ УСТРОЙСТВАМИ ОДНОГО ПОЛЬЗОВАТЕЛЯ ============\n        // Устройствa одного человека (телефон/планшет/ПК) держали баланс и коллекцию\n        // КАЖДЫЙ У СЕБЯ (localStorage). Теперь у пользователя есть облачный профиль:\n        //   • код профиля (создать на основном устройстве, ввести/открыть ссылку на остальных) —\n        //     главная привязка, не зависит от сети;\n        //   • авто-привязка по одному IP (b363) — если кода нет, устройства с одним IP\n        //     сами попадают в общий профиль (отключается тумблером).\n        // Баланс сливается по правилу «последнее состояние + дельты остальных»:\n        // устройство пушит не свой баланс, а ИЗМЕНЕНИЕ с момента своей прошлой\n        // синхронизации, которое прибавляется к общему значению. Прогресс\n        // (паки/карты/коллекция/альбомы/статистика) объединяется, счётчики — максимум.\n        const PROF_ALPHABET = \'ABCDEFGHJKMNPQRSTUVWXYZ23456789\';\n        function profHashIp(ip) { // короткий стабильный ключ из IP (сам IP в имя документа не пишем)\n            let h = 5381;\n            const s = String(ip || \'\');\n            for (let i = 0; i < s.length; i++) h = ((h * 33) ^ s.charCodeAt(i)) >>> 0;\n            return h.toString(36);\n        }\n        function profCode() { try { return String(LS.getItem(\'nx_prof_code\') || \'\').toUpperCase(); } catch (e) { return \'\'; } }\n        function profIpAuto() { try { return LS.getItem(\'nx_prof_ipauto\') !== \'0\'; } catch (e) { return true; } }\n        function profDocKey() { // ключ облачного документа профиля: код важнее IP\n            const c = profCode();\n            if (c) return \'c-\' + c.toLowerCase();\n            if (!profIpAuto()) return \'\';\n            const ip = nxPublicIp();\n            return ip ? \'i-\' + profHashIp(ip) : \'\';\n        }\n        function profPath(key) { return \'https://textdb.dev/api/data/nexus-tcg-prof-\' + key; }\n        function profNum(v) { const n = Math.floor(Number(v)); return isFinite(n) ? n : 0; }\n        function profMaxMap(a, b) {\n            const out = {};\n            const put = o => { if (!o || typeof o !== \'object\') return; for (const k in o) { const v = o[k]; if (typeof v === \'object\' && v) { const sub = profMaxMap(out[k], v); out[k] = sub; } else out[k] = Math.max(profNum(out[k]), profNum(v)); } };\n            put(a); put(b);\n            return out;\n        }\n        function profMaxStr(a, b) { return String(a || \'\') >= String(b || \'\') ? (a || b || \'\') : (b || \'\'); }\n        function profMergeState(L, R) { // L — локальный слепок, R — общий из облака (или null)\n            if (!R) return L;\n            const out = {};\n            const pm = {};\n            (R.packs || []).forEach(p => { if (p && p.id) pm[p.id] = p; });\n            (L.packs || []).forEach(p => { if (p && p.id) pm[p.id] = p; });\n            out.packs = Object.keys(pm).map(k => pm[k]);\n            const cm = {};\n            (R.cards || []).forEach(c => { if (c && c.id) cm[c.id] = c; });\n            (L.cards || []).forEach(c => { if (c && c.id) cm[c.id] = c; });\n            out.cards = Object.keys(cm).map(k => cm[k]);\n            out.collection = profMaxMap(R.collection, L.collection);\n            out.stats = profMaxMap(R.stats, L.stats);\n            out.achievements = profMaxMap(R.achievements, L.achievements);\n            out.pity = profMaxMap(R.pity, L.pity);\n            out.albumBonus = profMaxMap(R.albumBonus, L.albumBonus);\n            out.packStats = profMaxMap(R.packStats, L.packStats);\n            out.windowBuys = profMaxMap(R.windowBuys, L.windowBuys);\n            out.daily = {\n                lastClaimDate: profMaxStr(R.daily && R.daily.lastClaimDate, L.daily && L.daily.lastClaimDate) || null,\n                streak: Math.max(profNum(R.daily && R.daily.streak), profNum(L.daily && L.daily.streak)),\n                lastDurakWinDate: profMaxStr(R.daily && R.daily.lastDurakWinDate, L.daily && L.daily.lastDurakWinDate) || null\n            };\n            const md = String(R.missions && R.missions.date || \'\'), ld = String(L.missions && L.missions.date || \'\');\n            out.missions = (md > ld) ? R.missions : (ld > md ? L.missions : (L.missions && (L.missions.list || []).length >= ((R.missions && R.missions.list) || []).length ? L.missions : R.missions));\n            const dk = {};\n            (R.deck || []).forEach(id => { dk[id] = 1; });\n            (L.deck || []).forEach(id => { dk[id] = 1; });\n            out.deck = Object.keys(dk).filter(id => cm[id]);\n            return out;\n        }\n        function profSnap() { // слепок прогресса для облака (без тяжёлых артов: image-ссылки и так внутри паков/карт)\n            return {\n                coins: Math.max(0, Math.floor(state.coins) || 0),\n                packs: (state.packs || []).map(lightPack),\n                cards: (state.cards || []).map(lightCard),\n                collection: state.collection || {},\n                stats: state.stats || {},\n                daily: state.daily || {},\n                missions: state.missions || {},\n                achievements: state.achievements || {},\n                pity: state.pity || {},\n                deck: state.deck || [],\n                albumBonus: state.albumBonus || {},\n                packStats: state.packStats || {},\n                windowBuys: state.windowBuys || {}\n            };\n        }\n        function profApply(s, mlvl) { // приложить слитое состояние к игре\n            if (!s) return;\n            state.coins = Math.max(0, profNum(s.coins));\n            if (Array.isArray(s.packs)) state.packs = s.packs;\n            if (Array.isArray(s.cards)) state.cards = s.cards;\n            state.collection = s.collection || {};\n            state.stats = Object.assign({}, defaultStats, s.stats || {});\n            state.daily = Object.assign({ lastClaimDate: null, streak: 0, lastDurakWinDate: null }, s.daily || {});\n            state.missions = s.missions || { date: null, list: [] };\n            state.achievements = s.achievements || {};\n            state.pity = Object.assign({ packsSinceEpic: 0 }, s.pity || {});\n            state.deck = Array.isArray(s.deck) ? s.deck : [];\n            state.albumBonus = s.albumBonus || {};\n            state.packStats = s.packStats || {};\n            state.windowBuys = s.windowBuys || {};\n            try { // кирка шахты: уровень не теряется между устройствами\n                if (mlvl && typeof miner !== \'undefined\' && miner && mlvl > (miner.lvl || 0)) { miner.lvl = mlvl; try { minerSave(); } catch (e) {} }\n            } catch (e) {}\n            saveState();\n            updateCoinDisplay();\n            try { refreshVisibleTabs(); } catch (e) {}\n        }\n        function profMinerLvl() { try { return profNum((typeof miner !== \'undefined\' && miner) ? miner.lvl : 0); } catch (e) { return 0; } }\n        let profBusy = false, profLastRemote = null, profLastTs = 0, profT = 0;\n        function profFetch(key) {\n            return fetch(profPath(key) + \'?nc=\' + Date.now(), { cache: \'no-store\' }).then(r => {\n                if (!r.ok) throw new Error(\'HTTP \' + r.status);\n                return r.text();\n            }).then(txt => { try { return JSON.parse(String(txt || \'\').trim() || \'null\'); } catch (e) { return null; } });\n        }\n        function profPushDoc(key, doc, keepalive) {\n            return fetch(profPath(key), {\n                method: \'POST\',\n                headers: { \'Content-Type\': \'text/plain\' },\n                body: JSON.stringify(doc),\n                keepalive: !!keepalive\n            }).then(r => { if (!r.ok) throw new Error(\'HTTP \' + r.status); return true; });\n        }\n        function profBuildDoc(key, remote, mergedFields, mergedCoins) {\n            const did = nxDeviceId();\n            const book = Object.assign({}, (remote && remote.book) || {});\n            book[did] = { at: Date.now(), bal: mergedCoins, dev: nxDeviceLabel(), ip: nxPublicIp(), n: getPlayerName() };\n            return {\n                v: 1, ts: Date.now(), by: did, code: profCode(),\n                state: Object.assign({}, mergedFields, { coins: mergedCoins }),\n                minerLvl: Math.max(profMinerLvl(), profNum(remote && remote.minerLvl)),\n                book: book\n            };\n        }\n        function profSyncOnce(force) {\n            const key = profDocKey();\n            profUI();\n            if (!key) return Promise.resolve(false);\n            if (profBusy) return Promise.resolve(false);\n            profBusy = true;\n            const did = nxDeviceId();\n            let lastBal = parseInt(LS.getItem(\'nx_prof_lastbal\') || \'\', 10);\n            const first = !isFinite(lastBal);\n            if (first) lastBal = 0; // первое подключение: весь мой баланс — это моя дельта\n            return profFetch(key).then(remote => {\n                profLastRemote = remote;\n                const rState = remote && remote.state ? remote.state : null;\n                const myDelta = Math.max(0, Math.floor(state.coins) || 0) - lastBal;\n                const mergedFields = profMergeState(profSnap(), rState);\n                const mergedCoins = Math.max(0, (rState ? profNum(rState.coins) : 0) + myDelta);\n                const unionGrew = !rState\n                    || (mergedFields.cards || []).length > (rState.cards || []).length\n                    || (mergedFields.packs || []).length > (rState.packs || []).length;\n                const book = (remote && remote.book) || {};\n                const bookStale = !book[did] || (Date.now() - profNum(book[did].at) > 120000);\n                const needPush = !!force || !remote || myDelta !== 0 || unionGrew || bookStale;\n                // прикладываем общее состояние к себе (чужие карты/паки/баланс приезжают сюда).\n                // ВАЖНО: базой «моих изменений» становится именно слитое значение, иначе\n                // подтянутый прирост на следующем круге уехал бы в облако второй раз,\n                // а трата откатилась бы обратно (тест это ловил: +50 дублировались).\n                if (rState) {\n                    profApply(Object.assign({}, mergedFields, { coins: mergedCoins }), Math.max(profMinerLvl(), profNum(remote && remote.minerLvl)));\n                    try { LS.setItem(\'nx_prof_lastbal\', String(mergedCoins)); } catch (e) {}\n                }\n                profLastTs = Date.now();\n                if (!needPush) { profUI(); return true; }\n                const doc = profBuildDoc(key, remote, mergedFields, mergedCoins);\n                return profPushDoc(key, doc).then(() => {\n                    try { LS.setItem(\'nx_prof_lastbal\', String(mergedCoins)); } catch (e) {}\n                    profLastRemote = doc;\n                    // защита от перезаписи: читаем ещё раз, если между пушем и чтением\n                    // кто-то вписался — повторяем цикл слияния (максимум один раз)\n                    return profFetch(key).then(chk => {\n                        if (chk && chk.ts && doc.ts && String(chk.ts) !== String(doc.ts) && String(chk.by) !== did) {\n                            const r2 = chk.state || null;\n                            const d2 = Math.max(0, Math.floor(state.coins) || 0) - mergedCoins;\n                            const f2 = profMergeState(profSnap(), r2);\n                            const c2 = Math.max(0, (r2 ? profNum(r2.coins) : 0) + d2);\n                            profApply(Object.assign({}, f2, { coins: c2 }), Math.max(profMinerLvl(), profNum(chk && chk.minerLvl)));\n                            const doc2 = profBuildDoc(key, chk, f2, c2);\n                            return profPushDoc(key, doc2).then(() => { try { LS.setItem(\'nx_prof_lastbal\', String(c2)); } catch (e) {} });\n                        }\n                        return true;\n                    });\n                }).then(() => { profUI(); return true; });\n            }).catch(() => { profUI(); return false; })\n              .then(v => { profBusy = false; return v; });\n        }\n        function profSyncSoon() { clearTimeout(profT); profT = setTimeout(() => { profSyncOnce(false); }, 1500); }\n        function profFlush() { // аварийная отправка при скрытии вкладки: моя дельта не должна потеряться\n            try {\n                const key = profDocKey();\n                if (!key) return;\n                const lastBal = parseInt(LS.getItem(\'nx_prof_lastbal\') || \'\', 10);\n                const myDelta = Math.max(0, Math.floor(state.coins) || 0) - (isFinite(lastBal) ? lastBal : 0);\n                if (myDelta === 0 && profLastRemote) return;\n                const rState = profLastRemote && profLastRemote.state ? profLastRemote.state : null;\n                const fields = profMergeState(profSnap(), rState);\n                const coins = Math.max(0, (rState ? profNum(rState.coins) : 0) + myDelta);\n                profPushDoc(key, profBuildDoc(key, profLastRemote, fields, coins), true);\n            } catch (e) {}\n        }\n        function profGenCode() {\n            let c = \'\';\n            for (let i = 0; i < 6; i++) c += PROF_ALPHABET[Math.floor(Math.random() * PROF_ALPHABET.length)];\n            return c;\n        }\n        function profSetCode(code, silent) {\n            code = String(code || \'\').toUpperCase().replace(/[^A-Z0-9]/g, \'\').slice(0, 12);\n            try {\n                if (code) LS.setItem(\'nx_prof_code\', code); else LS.setItem(\'nx_prof_code\', \'\');\n                try { LS.removeItem(\'nx_prof_lastbal\'); } catch (e) {} // баланс пересчитаем с нуля против нового профиля\n            } catch (e) {}\n            profUI();\n            if (!silent) profSyncOnce(true);\n            return code;\n        }\n        function profCreateCode() {\n            const c = profSetCode(profGenCode());\n            try { showToast(\'Профиль создан: код \' + c + \'. Введите этот код (или откройте ссылку ?prof=\' + c + \') на остальных устройствах\', \'success\'); } catch (e) {}\n        }\n        function profEnterCode() {\n            const c = window.prompt(\'Код профиля с основного устройства (6 знаков) или ссылка с ?prof=…\');\n            if (!c) return;\n            const m = String(c).match(/prof=([a-z0-9-]+)/i);\n            const code = profSetCode(m ? m[1] : c);\n            if (code) { try { showToast(\'Код принят: \' + code + \' — синхронизирую…\', \'success\'); } catch (e) {} }\n        }\n        function profCopyLink() {\n            const c = profCode();\n            if (!c) { profCreateCode(); }\n            const link = location.origin + location.pathname + \'?prof=\' + (profCode() || c);\n            try { navigator.clipboard && navigator.clipboard.writeText(link); showToast(\'Ссылка скопирована: \' + link, \'success\'); } catch (e) { window.prompt(\'Скопируйте ссылку для других устройств:\', link); }\n        }\n        function profUnlink() {\n            try { LS.setItem(\'nx_prof_code\', \'\'); LS.removeItem(\'nx_prof_lastbal\'); } catch (e) {}\n            profLastRemote = null;\n            profUI();\n            try { showToast(\'Привязка снята: устройство снова само по себе\', \'info\'); } catch (e) {}\n        }\n        function profToggleIpAuto() {\n            try { LS.setItem(\'nx_prof_ipauto\', profIpAuto() ? \'0\' : \'1\'); LS.removeItem(\'nx_prof_lastbal\'); } catch (e) {}\n            profUI(); profSyncSoon();\n        }\n        function profLabel() {\n            const c = profCode();\n            if (c) return \'код \' + c;\n            if (!profIpAuto()) return \'выключен\';\n            const ip = nxPublicIp();\n            return ip ? \'авто по IP \' + ip : \'авто по IP (IP ещё не известен)\';\n        }\n        function profUI() {\n            const st = document.getElementById(\'nx-prof-status\');\n            if (st) {\n                const book = (profLastRemote && profLastRemote.book) ? Object.keys(profLastRemote.book).length : 0;\n                st.innerHTML =\n                    \'<span class="text-[10px] text-slate-400">Профиль: <b class="text-slate-200">\' + cloudEsc(profLabel()) + \'</b></span>\' +\n                    \'<span class="text-[10px] text-slate-500">устройств в профиле: <b class="text-slate-300">\' + book + \'</b></span>\' +\n                    \'<span class="text-[10px] text-slate-500">синхронизация: <b class="text-slate-300">\' + (profLastTs ? statsAgo(profLastTs) : \'ещё не была\') + \'</b></span>\';\n            }\n            const b = document.getElementById(\'nx-prof-ipauto-btn\');\n            if (b) b.innerHTML = \'<i class="fa-solid fa-location-dot mr-1"></i>Авто по IP: \' + (profIpAuto() ? \'вкл\' : \'выкл\');\n            const cc = document.getElementById(\'nx-prof-code-btn\');\n            if (cc) cc.innerHTML = profCode() ? \'<i class="fa-solid fa-key mr-1"></i>Сменить код\' : \'<i class="fa-solid fa-key mr-1"></i>Создать код\';\n        }\n        function profInit() {\n            try {\n                const m = String(location.search || \'\').match(/[?&]prof=([a-zA-Z0-9-]{4,12})/);\n                if (m) { profSetCode(m[1].toUpperCase(), true); try { showToast(\'Открыта ссылка профиля \' + m[1].toUpperCase() + \' — привязываю устройство…\', \'success\'); } catch (e) {} }\n            } catch (e) {}\n            profUI();\n            setTimeout(() => { profSyncOnce(false); }, 4000);\n            setInterval(() => { try { if (!document.hidden) profSyncOnce(false); } catch (e) {} }, 45000);\n            document.addEventListener(\'visibilitychange\', () => { try { if (document.hidden) profFlush(); else profSyncSoon(); } catch (e) {} });\n            window.addEventListener(\'pagehide\', () => { try { profFlush(); } catch (e) {} });\n        }\n        function nxStatsGroupOn() {'),
